import{_ as t,o as n,c as a,a2 as d}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"Wie sind die Datenpunkte aufgebaut und wie schreibe ich sie?","description":"","frontmatter":{"order":2,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/de/03.referenz/02.datenpunkte.md"},"headers":[],"relativePath":"de/adapter/esphome/referenz/datenpunkte.md","filePath":"de/adapter/esphome/referenz/datenpunkte.md","lastUpdated":null}'),i={name:"de/adapter/esphome/referenz/datenpunkte.md"};function s(r,e,o,c,l,u){return n(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="wie-sind-die-datenpunkte-aufgebaut-und-wie-schreibe-ich-sie" tabindex="-1">Wie sind die Datenpunkte aufgebaut und wie schreibe ich sie? <a class="header-anchor" href="#wie-sind-die-datenpunkte-aufgebaut-und-wie-schreibe-ich-sie" aria-label="Permalink to &quot;Wie sind die Datenpunkte aufgebaut und wie schreibe ich sie?&quot;">​</a></h1><p><a id="datapoint-path-contain-number-instead"></a></p><h2 id="warum-steht-im-datenpunkt-pfad-eine-zahl-statt-des-sensornamens" tabindex="-1">Warum steht im Datenpunkt-Pfad eine Zahl statt des Sensornamens? <a class="header-anchor" href="#warum-steht-im-datenpunkt-pfad-eine-zahl-statt-des-sensornamens" aria-label="Permalink to &quot;Warum steht im Datenpunkt-Pfad eine Zahl statt des Sensornamens?&quot;">​</a></h2><p>Die Zahl ist der Schlüssel, den ESPHome der Entität gibt. Der Adapter baut jeden Pfad so auf:</p><p><code>esphome.0.&lt;Gerät&gt;.&lt;Typ&gt;.&lt;Schlüssel&gt;.&lt;Datenpunkt&gt;</code>, z. B. <code>esphome.0.A1B2C3D4E5F6.Sensor.1234567890.state</code></p><table tabindex="0"><thead><tr><th>Teil</th><th>Inhalt</th></tr></thead><tbody><tr><td><code>&lt;Gerät&gt;</code></td><td>MAC-Adresse ohne Doppelpunkte</td></tr><tr><td><code>&lt;Typ&gt;</code></td><td>Art der Entität, z. B. <code>Sensor</code>, <code>Switch</code>, <code>Light</code></td></tr><tr><td><code>&lt;Schlüssel&gt;</code></td><td>Schlüssel der Entität aus der API</td></tr><tr><td><code>&lt;Datenpunkt&gt;</code></td><td>meist <code>state</code>, bei Lampen, Covern und Lüftern mehrere</td></tr></tbody></table><p>Den lesbaren Namen aus der YAML zeigt der Tab „Objekte“ in der Spalte „Name“ am Ordner der Entität. Den Pfad kann der Adapter nicht ändern. Benennst du die Entität in der YAML um, ändert ESPHome den Schlüssel, und der Pfad wird neu. Den alten Ordner räumt der Adapter nach der Verbindung weg.</p><p>Willst du feste, lesbare Namen, leg einen Alias an.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/automatisieren#use-esphome-datapoints-aliases-alexa">Aliase anlegen</a> · <a href="./../anleitungen/geraete-verwalten#clean-up-devices-datapoints-no">Alte Datenpunkte aufräumen</a></p><p><a id="online-status-wifi-signal-ip"></a></p><h2 id="wo-finde-ich-online-status-wlan-signal-ip-und-laufzeit-eines-gerats" tabindex="-1">Wo finde ich Online-Status, WLAN-Signal, IP und Laufzeit eines Geräts? <a class="header-anchor" href="#wo-finde-ich-online-status-wlan-signal-ip-und-laufzeit-eines-gerats" aria-label="Permalink to &quot;Wo finde ich Online-Status, WLAN-Signal, IP und Laufzeit eines Geräts?&quot;">​</a></h2><p>Ob ein Gerät verbunden ist, zeigt <code>esphome.0.&lt;Gerät&gt;.info._online</code>: <code>true</code>, solange die Verbindung steht, sonst <code>false</code>. Der Datenpunkt hat die Rolle <code>indicator.reachable</code>. Den genauen Zustand, z. B. <code>unreachable</code> oder <code>Encryption Key Missing</code>, zeigt <code>info._connectionStatus</code>.</p><p>Für die ganze Instanz gibt es zwei Datenpunkte:</p><table tabindex="0"><thead><tr><th>Datenpunkt</th><th>Inhalt</th></tr></thead><tbody><tr><td><code>esphome.0.info.connection</code></td><td><code>true</code>, solange der Adapter läuft</td></tr><tr><td><code>esphome.0.info.connectedDevices</code></td><td>Namen der verbundenen Geräte, durch Komma getrennt. Mit eingeschaltetem Dashboard bleibt die Liste leer, bis das Dashboard antwortet.</td></tr></tbody></table><p>WLAN-Signal, IP-Adresse und Laufzeit meldet ESPHome nur, wenn sie als Sensoren in der YAML stehen, z. B. <code>wifi_signal</code>, <code>uptime</code> und <code>wifi_info</code>. Sie erscheinen dann unter <code>Sensor</code> bzw. <code>TextSensor</code> des Geräts. Ein <code>wifi_signal</code>-Sensor zeigt das Signal zusätzlich auf der Karte des Geräts im Reiter „Geräte“.</p><p><a id="command-acknowledged-ack-happens-offline"></a></p><h2 id="wann-gilt-ein-befehl-als-bestatigt-ack-und-was-passiert-bei-einem-offline-gerat" tabindex="-1">Wann gilt ein Befehl als bestätigt (ack) und was passiert bei einem Offline-Gerät? <a class="header-anchor" href="#wann-gilt-ein-befehl-als-bestatigt-ack-und-was-passiert-bei-einem-offline-gerat" aria-label="Permalink to &quot;Wann gilt ein Befehl als bestätigt (ack) und was passiert bei einem Offline-Gerät?&quot;">​</a></h2><p>Schreibst du einen Datenpunkt, steht er zunächst mit <code>ack = false</code> da. Der Adapter schickt den Befehl ans Gerät. Bestätigt (<code>ack = true</code>) ist der Wert erst, wenn das Gerät seinen neuen Zustand meldet.</p><p>Einige Datenpunkte meldet das Gerät nie zurück, sie bleiben unbestätigt: <code>SET</code> eines Buttons, <code>command</code> eines Schlosses und <code>stop</code> eines Covers. <code>config.rgbAutoWhite</code> bestätigt der Adapter selbst.</p><p>Ist das Gerät nicht verbunden, schickt der Adapter nichts. Der Wert bleibt auf <code>ack = false</code>, und im Log steht <code>[onStateChange] Device &lt;Gerät&gt; is not connected, command &lt;Datenpunkt&gt; not sent</code>. Skripte erkennen so, dass der Befehl nicht angekommen ist. Prüf dann <code>info._online</code> des Geräts.</p><p><strong>Siehe auch:</strong> <a href="#online-status-wifi-signal-ip">Online-Status eines Geräts</a></p>',21)])])}const f=t(i,[["render",s]]);export{p as __pageData,f as default};
